-- SPDX-License-Identifier: GPL-3.0-or-later
-- T88 D7: the host's C64 key matrix (keys[col*8+row], 1 = down) into the Atari 800 XL keyboard: pressed(code) for the 64 key
-- codes POKEY scans, and the shift / control / break / START / SELECT / OPTION lines. Generated by cores/atari800/sim/keymap.py;
-- do not edit by hand. The decisions of the mapping are in that file's header and in docs/specs/T88-atari800-core.md D7.
library ieee;
use ieee.std_logic_1164.all;

entity a8_keys is
  port (
    keys    : in  std_logic_vector(63 downto 0);
    pressed : out std_logic_vector(63 downto 0);   -- indexed by the Atari key code
    shift   : out std_logic;
    ctrl    : out std_logic;
    brk     : out std_logic;
    cstart  : out std_logic;                        -- 1 = down
    cselect : out std_logic;
    coption : out std_logic);
end entity;

architecture rtl of a8_keys is
  signal host_shift, cur_d, cur_r, cur : std_logic;
begin
  host_shift <= keys(15) or keys(52);   -- LSHIFT, RSHIFT
  cur_d <= keys(7);   -- CRSR down
  cur_r <= keys(2);   -- CRSR right
  cur   <= cur_d or cur_r;
  pressed(0) <= keys(42);   -- L
  pressed(1) <= keys(34);   -- J
  pressed(2) <= keys(45) or keys(50);   -- ;
  pressed(3) <= '0';   -- F1 (no host key)
  pressed(4) <= '0';   -- F2 (no host key)
  pressed(5) <= keys(37);   -- K
  pressed(6) <= (cur_r and host_shift) or keys(40) or keys(48);   -- +
  pressed(7) <= (cur_r and not host_shift) or keys(49) or keys(54);   -- *
  pressed(8) <= keys(38);   -- O
  pressed(9) <= '0';
  pressed(10) <= keys(41);   -- P
  pressed(11) <= keys(30);   -- U
  pressed(12) <= keys(1);   -- RETURN
  pressed(13) <= keys(33);   -- I
  pressed(14) <= (cur_d and host_shift) or keys(43);   -- -
  pressed(15) <= (cur_d and not host_shift) or keys(53);   -- =
  pressed(16) <= keys(31);   -- V
  pressed(17) <= keys(3);   -- HELP
  pressed(18) <= keys(20);   -- C
  pressed(19) <= '0';   -- F3 (no host key)
  pressed(20) <= '0';   -- F4 (no host key)
  pressed(21) <= keys(28);   -- B
  pressed(22) <= keys(23);   -- X
  pressed(23) <= keys(12);   -- Z
  pressed(24) <= keys(11);   -- 4
  pressed(25) <= '0';
  pressed(26) <= keys(8);   -- 3
  pressed(27) <= keys(19);   -- 6
  pressed(28) <= keys(57);   -- ESC
  pressed(29) <= keys(16);   -- 5
  pressed(30) <= keys(59);   -- 2
  pressed(31) <= keys(56);   -- 1
  pressed(32) <= keys(47);   -- ,
  pressed(33) <= keys(60);   -- SPACE
  pressed(34) <= keys(44);   -- .
  pressed(35) <= keys(39);   -- N
  pressed(36) <= '0';
  pressed(37) <= keys(36);   -- M
  pressed(38) <= keys(55);   -- /
  pressed(39) <= keys(61);   -- INVERSE
  pressed(40) <= keys(17);   -- R
  pressed(41) <= '0';
  pressed(42) <= keys(14);   -- E
  pressed(43) <= keys(25);   -- Y
  pressed(44) <= '0';   -- TAB (no host key)
  pressed(45) <= keys(22);   -- T
  pressed(46) <= keys(9);   -- W
  pressed(47) <= keys(62);   -- Q
  pressed(48) <= keys(32);   -- 9
  pressed(49) <= '0';
  pressed(50) <= keys(35);   -- 0
  pressed(51) <= keys(24);   -- 7
  pressed(52) <= keys(0);   -- BACKSPACE
  pressed(53) <= keys(27) or keys(46);   -- 8
  pressed(54) <= keys(51);   -- <
  pressed(55) <= '0';   -- > (no host key)
  pressed(56) <= keys(21);   -- F
  pressed(57) <= keys(29);   -- H
  pressed(58) <= keys(18);   -- D
  pressed(59) <= '0';
  pressed(60) <= '0';   -- CAPS (no host key)
  pressed(61) <= keys(26);   -- G
  pressed(62) <= keys(13);   -- S
  pressed(63) <= keys(10);   -- A
  shift   <= (host_shift and not cur) or keys(45) or keys(46) or keys(48) or keys(51) or keys(54);
  ctrl    <= keys(58) or cur;   -- CTRL, or a cursor key
  brk     <= keys(63);   -- RUN/STOP
  cstart  <= keys(4);   -- F1
  cselect <= keys(5);   -- F3
  coption <= keys(6);   -- F5
end architecture;
